import { Controller } from "@hotwired/stimulus"
import Chart from 'chart.js/auto';

export default class extends Controller {
    connect() {
        this.buildCharts()
    }

    buildCharts() {
        if(document.getElementById('chart-sample-a')){
            const chartA = new Chart(document.getElementById('chart-sample-a').getContext('2d'), {
                type: 'bar',
                data: {
                    labels: ['Red', 'Blue', 'Yellow', 'Green', 'Purple', 'Orange'],
                    datasets: [{
                        label: '# of Votes',
                        data: [12, 19, 3, 5, 2, 3],
                        backgroundColor: [
                            'rgba(255, 99, 132, 0.2)',
                            'rgba(54, 162, 235, 0.2)',
                            'rgba(255, 206, 86, 0.2)',
                            'rgba(75, 192, 192, 0.2)',
                            'rgba(153, 102, 255, 0.2)',
                            'rgba(255, 159, 64, 0.2)'
                        ],
                        borderColor: [
                            'rgba(255, 99, 132, 1)',
                            'rgba(54, 162, 235, 1)',
                            'rgba(255, 206, 86, 1)',
                            'rgba(75, 192, 192, 1)',
                            'rgba(153, 102, 255, 1)',
                            'rgba(255, 159, 64, 1)'
                        ],
                        borderWidth: 1
                    }]
                },
                options: {
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }

        if(document.getElementById('chart-sample-b')){
            const chartB = new Chart(document.getElementById('chart-sample-b').getContext('2d'), {
                type: 'line',
                data: {
                    labels: ['M', 'T', 'W', 'T', 'F', 'S', 'S'],
                    datasets: [{
                        label: 'Orders Shipped',
                        data: [13, 19, 9, 13, 6, 3, 7],
                        backgroundColor: "rgba(26, 100, 156,0.6)"
                    }, {
                        label: 'Orders Placed',
                        data: [5, 29, 5, 5, 2, 3, 10],
                        backgroundColor: "rgba(71, 175, 225,0.4)"
                    }]
                }
            });
        }
    }
}